(function() {
  'use strict';

  // Constants for the teaching example
  // Fixed Keys and Values for the demonstration
  const K1 = [2.0, 0.0];
  const K2 = [0.0, 2.0];
  const V1 = [10, 0];
  const V2 = [0, 10];

  // DOM Elements
  const inputQx = document.getElementById('input-qx');
  const inputQy = document.getElementById('input-qy');
  const dispQ = document.getElementById('disp-q');

  const barScore1 = document.getElementById('bar-score-1');
  const valScore1 = document.getElementById('val-score-1');
  const barScore2 = document.getElementById('bar-score-2');
  const valScore2 = document.getElementById('val-score-2');

  const barWeight1 = document.getElementById('bar-weight-1');
  const valWeight1 = document.getElementById('val-weight-1');
  const barWeight2 = document.getElementById('bar-weight-2');
  const valWeight2 = document.getElementById('val-weight-2');

  const dispOutput = document.getElementById('disp-output');
  const contrib1 = document.getElementById('contrib-1');
  const contrib2 = document.getElementById('contrib-2');

  // Helper: Dot Product
  function dot(v1, v2) {
    return v1[0] * v2[0] + v1[1] * v2[1];
  }

  // Helper: Softmax
  function softmax(scores) {
    const maxScore = Math.max(...scores);
    const exps = scores.map(s => Math.exp(s - maxScore));
    const sumExps = exps.reduce((a, b) => a + b, 0);
    return exps.map(e => e / sumExps);
  }

  // Helper: Vector Add
  function addScaled(v1, s1, v2, s2) {
    return [
      v1[0] * s1 + v2[0] * s2,
      v1[1] * s1 + v2[1] * s2
    ];
  }

  // Main Update Function
  function updateAttention() {
    // 1. Get Query Input
    const qx = parseFloat(inputQx.value);
    const qy = parseFloat(inputQy.value);
    const Q = [qx, qy];

    // Update Q Display
    dispQ.textContent = `[${qx.toFixed(1)}, ${qy.toFixed(1)}]`;

    // 2. Calculate Compatibility (Dot Product)
    // Note: In full Scaled Dot-Product, we divide by sqrt(d_k), here d_k=2, sqrt(2)~1.41
    // For teaching clarity on "Weighted Sum", we show raw scores then normalize.
    const score1 = dot(Q, K1);
    const score2 = dot(Q, K2);

    // Update Score Bars (Visual scaling for display, max range approx +/- 10)
    const maxScoreRange = 10;
    const pct1 = Math.min(100, Math.max(0, ((score1 + maxScoreRange) / (maxScoreRange * 2)) * 100));
    const pct2 = Math.min(100, Math.max(0, ((score2 + maxScoreRange) / (maxScoreRange * 2)) * 100));

    barScore1.style.width = `${pct1}%`;
    valScore1.textContent = score1.toFixed(2);
    barScore2.style.width = `${pct2}%`;
    valScore2.textContent = score2.toFixed(2);

    // 3. Calculate Weights (Softmax)
    const weights = softmax([score1, score2]);
    const w1 = weights[0];
    const w2 = weights[1];

    // Update Weight Bars
    barWeight1.style.width = `${w1 * 100}%`;
    valWeight1.textContent = w1.toFixed(3);
    barWeight2.style.width = `${w2 * 100}%`;
    valWeight2.textContent = w2.toFixed(3);

    // 4. Calculate Output (Weighted Sum)
    // Output = w1 * V1 + w2 * V2
    const output = addScaled(V1, w1, V2, w2);

    // Update Output Display
    dispOutput.textContent = `[${output[0].toFixed(1)}, ${output[1].toFixed(1)}]`;

    // Update Contribution Visualization
    // Since V1 is [10, 0] and V2 is [0, 10], the output components directly reflect the weights * 10
    // We visualize the magnitude of contribution to the final vector magnitude roughly
    const contribPct1 = w1 * 100;
    const contribPct2 = w2 * 100;

    contrib1.style.width = `${contribPct1}%`;
    contrib2.style.width = `${contribPct2}%`;
  }

  // Initialize Event Listeners
  if (inputQx && inputQy) {
    inputQx.addEventListener('input', updateAttention);
    inputQy.addEventListener('input', updateAttention);
  }

  // Initial Run
  updateAttention();

  // Source Button Handler (Delegated to Kernel via data attribute, no JS logic needed)
  // But we ensure the button exists and is accessible
  const sourceBtn = document.querySelector('.pm-btn-source');
  if (sourceBtn) {
    sourceBtn.addEventListener('click', function(e) {
      // The kernel handles the data-source attribute
      // No alert or mock behavior
    });
  }

})();
